ruleContent.content:
id.playleft@iframe@src||class.playerbox@iframe.-1@src||all
@js:
user=source.getLoginInfoMap();
num1=user['腾讯视频播放接口，输入数字，从0开始']
num2=user['哔哩哔哩播放接口，输入数字，从0开始']
eval(String(source.bookSourceComment))
if(baseUrl.match(/v.qq.com/)){
result=jiexi[num1==""?1:num1]+baseUrl
}else if(baseUrl.match(/bilibili.com/)){
result=jiexi[num2==""?1:num2]+baseUrl
}else if(baseUrl.match(/52gen/)){
	result=baseUrl.replace(/\/play.*/,'')+result
}

if(book.durChapterIndex==chapter.index){
		java.startBrowser(result,title)
		java.toast('正在加载视频\n视频加载较慢，请耐心等待')
	}
'当前接口总数为'+jiexi.length+'\n【刷新正文】播放\n✅直链:\n'+result

